        // 五点描述（用于 AI 对比）
        fulfillment: varchar("fulfillment", { length: 20 }),
        // 配送方式: FBA/FBM/AMZ
        // === v8.2 竞品来源追踪 ===
        source: varchar("source", { length: 32 }).default("manual"),
        // manual / bsr_analysis / reverse_expansion
        // === v6.0 多榜单来源 ===
        chartSource: varchar("chart_source", { length: 32 }),
        // best_sellers / new_releases / most_wished / most_gifted
        chartRank: int("chart_rank"),
