function extractAsin(url) {
  const match = url.match(/\/dp\/([A-Z0-9]{10})/i) || url.match(/\/([A-Z0-9]{10})(?:[/?]|$)/);
  return match ? match[1] : null;
}
function calculateStats(values) {
  if (values.length === 0) return { min: 0, max: 0, avg: 0, median: 0, count: 0 };
  const sorted = [...values].sort((a, b) => a - b);
  return {
    min: sorted[0],
    max: sorted[sorted.length - 1],
    avg: parseFloat((values.reduce((s, v) => s + v, 0) / values.length).toFixed(2)),
    median: sorted[Math.floor(sorted.length / 2)],
    count: values.length
  };
}
function buildDistribution(values, buckets) {
  return buckets.map((b) => ({
    label: b.label,
    count: values.filter((v) => v >= b.min && v < b.max).length,
    percentage: values.length > 0 ? parseFloat((values.filter((v) => v >= b.min && v < b.max).length / values.length * 100).toFixed(1)) : 0
  }));
}

