function percentileRank(value, allValues, higherIsBetter) {
  if (allValues.length === 0) return 50;
  const sorted = [...allValues].sort((a, b) => a - b);
  let rank = sorted.filter((v) => v < value).length;
  const ties = sorted.filter((v) => v === value).length;
  rank += ties / 2;
  const percentile2 = rank / sorted.length * 100;
  return higherIsBetter ? percentile2 : 100 - percentile2;
}
