async function notifyOwner(opts) {
  console.log(`[Notification] ${opts.title}: ${opts.content}`);
  const webhookUrl = process.env.NOTIFICATION_WEBHOOK_URL;
  if (!webhookUrl) {
    return true;
  }
  try {
    const response = await fetch(webhookUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: opts.title,
        content: opts.content,
        timestamp: (/* @__PURE__ */ new Date()).toISOString(),
        source: "AmzOrbit"
      })
    });
    if (!response.ok) {
      console.warn(`[notifyOwner] Webhook HTTP ${response.status}: ${await response.text()}`);
      return false;
    }
    return true;
  } catch (error) {
    console.warn(`[notifyOwner] Webhook failed: ${error.message}`);
    return true;
  }
}
// === Bridge API Resilience Layer (v26.7.1) ===
const _bridgeCallLog = [];
const BRIDGE_MAX_LOG_ENTRIES = 500;

async function bridgeFetchWithRetry(url, options = {}, retryConfig = {}) {
  // === Dual-Key: Inject HMAC signature if aKey is provided ===
  if (retryConfig.aKey && retryConfig.pKey) {
    const bodyStr = options.body || "";
    const timestamp = new Date().toISOString();
    const signature = bridgeHmacSign(retryConfig.aKey, bodyStr + timestamp);
    options.headers = options.headers || {};
    options.headers["Authorization"] = "Bearer " + retryConfig.pKey;
    options.headers["X-Bridge-Signature"] = signature;
    options.headers["X-Bridge-Timestamp"] = timestamp;
    options.headers["X-Bridge-Scope"] = retryConfig.scopeId || "";
  }
  // === End Dual-Key injection ===
  const { maxRetries = 3, baseDelay = 1000, maxDelay = 15000, endpoint = "unknown", projectId = null, silent = false } = retryConfig;
  let lastError = null;
  const startTime = Date.now();
  
  for (let attempt = 1; attempt <= maxRetries + 1; attempt++) {
    const attemptStart = Date.now();
    try {
      const resp = await fetch(url, options);
      const elapsed = Date.now() - attemptStart;
      
      // Log successful call
      _bridgeCallLog.push({
        ts: new Date().toISOString(),
        endpoint,
        url: url.replace(/brk_[a-zA-Z0-9]+/, "brk_***"),
        method: options.method || "GET",
        status: resp.status,
        attempt,
        elapsed,
        projectId,
        success: resp.ok
      });
      if (_bridgeCallLog.length > BRIDGE_MAX_LOG_ENTRIES) _bridgeCallLog.shift();
      
      if (resp.ok) {
        return resp;
      }
      
      // Non-retryable HTTP errors (4xx except 429)
      if (resp.status >= 400 && resp.status < 500 && resp.status !== 429) {
        const errText = await resp.text();
        const err = new Error(`Bridge API ${endpoint} HTTP ${resp.status}: ${errText}`);
        err.httpStatus = resp.status;
        err.responseBody = errText;
        
        // Log and alert for client errors
        _bridgeCallLog.push({
          ts: new Date().toISOString(),
          endpoint,
          url: url.replace(/brk_[a-zA-Z0-9]+/, "brk_***"),
          method: options.method || "GET",
          status: resp.status,
          attempt,
          elapsed,
          projectId,
          success: false,
          error: errText.substring(0, 200)
        });
        if (_bridgeCallLog.length > BRIDGE_MAX_LOG_ENTRIES) _bridgeCallLog.shift();
        
        throw err;
      }
      
      // Retryable: 5xx or 429
      lastError = new Error(`Bridge API ${endpoint} HTTP ${resp.status}`);
      lastError.httpStatus = resp.status;
      console.warn(`[Bridge Retry] ${endpoint} attempt ${attempt}/${maxRetries + 1} failed with HTTP ${resp.status}`);
      
    } catch (fetchErr) {
      if (fetchErr.httpStatus && fetchErr.httpStatus >= 400 && fetchErr.httpStatus < 500 && fetchErr.httpStatus !== 429) {
        throw fetchErr;
      }
      lastError = fetchErr;
      console.warn(`[Bridge Retry] ${endpoint} attempt ${attempt}/${maxRetries + 1} error: ${fetchErr.message}`);
    }
    
    // Don't delay after the last attempt
    if (attempt <= maxRetries) {
      const delay = Math.min(baseDelay * Math.pow(2, attempt - 1) + Math.random() * 500, maxDelay);
      console.log(`[Bridge Retry] ${endpoint} waiting ${Math.round(delay)}ms before retry ${attempt + 1}...`);
      await new Promise(r => setTimeout(r, delay));
    }
  }
  
  // All retries exhausted - log failure and send alert
  const totalElapsed = Date.now() - startTime;
  _bridgeCallLog.push({
    ts: new Date().toISOString(),
    endpoint,
    url: url.replace(/brk_[a-zA-Z0-9]+/, "brk_***"),
    method: options.method || "GET",
    status: "EXHAUSTED",
    attempt: maxRetries + 1,
    elapsed: totalElapsed,
    projectId,
    success: false,
    error: lastError?.message?.substring(0, 200) || "unknown"
  });
  if (_bridgeCallLog.length > BRIDGE_MAX_LOG_ENTRIES) _bridgeCallLog.shift();
  
  // Send alert notification
  if (!silent) {
    await notifyOwner({
      title: `\u26A0\uFE0F Bridge API \u8C03\u7528\u5931\u8D25\u544A\u8B66`,
      content: `\u7AEF\u70B9: ${endpoint}\n\u91CD\u8BD5\u6B21\u6570: ${maxRetries + 1}\n\u603B\u8017\u65F6: ${totalElapsed}ms\n\u9519\u8BEF: ${lastError?.message || "unknown"}\n\u9879\u76EE: ${projectId || "N/A"}\n\u65F6\u95F4: ${new Date().toISOString()}`
    });
  }
  
  throw new Error(`Bridge API ${endpoint} \u5728 ${maxRetries + 1} \u6B21\u5C1D\u8BD5\u540E\u4ECD\u7136\u5931\u8D25: ${lastError?.message || "unknown"}`);
}

function getBridgeCallStats() {
  const now = Date.now();
  const last24h = _bridgeCallLog.filter(l => (now - new Date(l.ts).getTime()) < 86400000);
  const last1h = last24h.filter(l => (now - new Date(l.ts).getTime()) < 3600000);
  
  const calcStats = (logs) => {
    const total = logs.length;
    const success = logs.filter(l => l.success).length;
    const failed = logs.filter(l => !l.success).length;
    const avgElapsed = total > 0 ? Math.round(logs.reduce((s, l) => s + (l.elapsed || 0), 0) / total) : 0;
    const byEndpoint = {};
    for (const l of logs) {
      if (!byEndpoint[l.endpoint]) byEndpoint[l.endpoint] = { total: 0, success: 0, failed: 0 };
      byEndpoint[l.endpoint].total++;
      if (l.success) byEndpoint[l.endpoint].success++;
      else byEndpoint[l.endpoint].failed++;
    }
    return { total, success, failed, successRate: total > 0 ? ((success / total) * 100).toFixed(1) + "%" : "N/A", avgElapsed, byEndpoint };
  };
  
  return {
    last1h: calcStats(last1h),
    last24h: calcStats(last24h),
    recentCalls: _bridgeCallLog.slice(-20).reverse()
  };
}
// === End Bridge API Resilience Layer ===


