async function analyzeReviewSentiment(params) {
  const startTime = Date.now();
  try {
    const response = await invokeLLM({
      messages: [
        {
          role: "system",
          content: `You are a product review analyst. For each review, determine:
1. Overall sentiment (positive/negative/neutral)
2. Pain points mentioned (things the customer didn't like)
3. Praised features (things the customer liked)

Return JSON array with objects containing: id, sentiment, painPoints (string array), praisedFeatures (string array).`
        },
        {
          role: "user",
          content: `Analyze these reviews:
${params.reviews.map((r) => `[ID: ${r.id}, Rating: ${r.rating}] ${r.content}`).join("\n\n")}`
        }
      ],
      response_format: {
        type: "json_schema",
        json_schema: {
          name: "review_analysis",
          strict: true,
          schema: {
            type: "object",
            properties: {
              results: {
                type: "array",
                items: {
                  type: "object",
                  properties: {
                    id: { type: "string" },
                    sentiment: { type: "string" },
                    painPoints: { type: "array", items: { type: "string" } },
                    praisedFeatures: { type: "array", items: { type: "string" } }
                  },
                  required: ["id", "sentiment", "painPoints", "praisedFeatures"],
                  additionalProperties: false
                }
              }
            },
            required: ["results"],
            additionalProperties: false
          }
        }
      },
      temperature: 0.3
    });
    const content = response.choices[0]?.message?.content;
    const parsed = JSON.parse(content || "{}");
    const results = parsed.results || [];
    await logApiUsage({
      userId: params.userId,
      projectId: params.projectId,
      service: "gemini",
      endpoint: "review_analysis",
      success: true,
      responseTimeMs: Date.now() - startTime
    });
    return results;
  } catch (error) {
    await logApiUsage({
      userId: params.userId,
      projectId: params.projectId,
      service: "gemini",
      endpoint: "review_analysis",
      success: false,
      errorMessage: error.message,
      responseTimeMs: Date.now() - startTime
    });
    throw error;
  }
}

