var BASE_URL = "https://generativelanguage.googleapis.com/v1beta";
async function callGemini(request) {
  const apiKey = env.GOOGLE_AI_STUDIO_API_KEY;
  if (!apiKey) throw new Error("GOOGLE_AI_STUDIO_API_KEY not configured");
  const url = `${BASE_URL}/models/${request.model}:generateContent?key=${apiKey}`;
  const body = {
    contents: request.contents
  };
  if (request.systemInstruction) {
    body.system_instruction = request.systemInstruction;
  }
  if (request.generationConfig) {
    body.generation_config = {
      temperature: request.generationConfig.temperature,
      top_p: request.generationConfig.topP,
      top_k: request.generationConfig.topK,
      max_output_tokens: request.generationConfig.maxOutputTokens,
      response_mime_type: request.generationConfig.responseMimeType,
      response_schema: request.generationConfig.responseSchema
    };
    Object.keys(body.generation_config).forEach((k) => {
      if (body.generation_config[k] === void 0) delete body.generation_config[k];
    });
  }
  const response = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body)
  });
  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Gemini API error (${response.status}): ${errorText}`);
  }
  return response.json();
}
function extractText(response) {
  return response.candidates?.[0]?.content?.parts?.map((p) => p.text || "").join("") || "";
}
function extractJSON(response) {
  const text2 = extractText(response);
  const jsonMatch = text2.match(/```json\s*([\s\S]*?)```/) || text2.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const jsonStr = jsonMatch[1] || jsonMatch[0];
    return JSON.parse(jsonStr);
  }
  return JSON.parse(text2);
}
async function imageUrlToBase64(imageUrl) {
  const response = await fetch(imageUrl);
  if (!response.ok) throw new Error(`Failed to fetch image: ${imageUrl}`);
  const buffer = await response.arrayBuffer();
  const data = Buffer.from(buffer).toString("base64");
  const contentType = response.headers.get("content-type") || "image/jpeg";
  let mimeType = "image/jpeg";
  if (contentType.includes("png")) mimeType = "image/png";
  else if (contentType.includes("webp")) mimeType = "image/webp";
  else if (contentType.includes("gif")) mimeType = "image/gif";
  return { data, mimeType };
}
async function geminiText(model, systemPrompt, userPrompt, options) {
  const request = {
    model,
    contents: [{ role: "user", parts: [{ text: userPrompt }] }],
    systemInstruction: { parts: [{ text: systemPrompt }] },
    generationConfig: {
      temperature: options?.temperature ?? 0.3,
      maxOutputTokens: options?.maxTokens ?? 8192,
      ...options?.jsonMode ? { responseMimeType: "application/json" } : {}
    }
  };
  const response = await callGemini(request);
  return extractText(response);
}
async function geminiVision(model, systemPrompt, textPrompt, imageUrls, options) {
  const imageParts = [];
  for (const url of imageUrls) {
    try {
      const { data, mimeType } = await imageUrlToBase64(url);
      imageParts.push({ inline_data: { mime_type: mimeType, data } });
    } catch (e) {
      console.warn(`Failed to fetch image ${url}:`, e);
    }
  }
  const parts = [
    { text: textPrompt },
    ...imageParts
  ];
  const request = {
    model,
    contents: [{ role: "user", parts }],
    systemInstruction: { parts: [{ text: systemPrompt }] },
    generationConfig: {
      temperature: options?.temperature ?? 0.2,
      maxOutputTokens: options?.maxTokens ?? 8192,
      ...options?.jsonMode ? { responseMimeType: "application/json" } : {}
    }
  };
  const response = await callGemini(request);
  return extractText(response);
}

