  const audienceScore = seedAttrs.targetAudience.toLowerCase() === candidateAttrs.targetAudience.toLowerCase() ? 100 : seedAttrs.targetAudience === "general" || candidateAttrs.targetAudience === "general" ? 70 : 30;
  const scenarioScore = seedAttrs.primaryScenario.toLowerCase() === candidateAttrs.primaryScenario.toLowerCase() ? 100 : seedAttrs.primaryScenario === "general" || candidateAttrs.primaryScenario === "general" ? 60 : 25;
  const seedFeatures = new Set(seedAttrs.features.map((f) => f.toLowerCase()));
