async function verifyCompetitors(seedProduct, candidates) {
  console.log(`[AI Verification] Starting verification of ${candidates.length} candidates against seed ${seedProduct.asin}`);
  console.log(`[AI Verification] Stage 0: Extracting structured attributes...`);
  const allProducts = [
    { asin: seedProduct.asin, title: seedProduct.title, bulletPoints: seedProduct.bulletPoints, description: seedProduct.description, images: seedProduct.images },
    ...candidates.map((c) => ({ asin: c.asin, title: c.title, bulletPoints: c.bulletPoints, description: c.description, images: c.images }))
  ];
  const attributeMap = await stage0ExtractAttributes(allProducts);
  const seedAttrs = attributeMap.get(seedProduct.asin);
  console.log(`[AI Verification] Stage 0 complete: extracted attributes for ${attributeMap.size} products`);
  console.log(`[AI Verification] Stage 1: Visual screening with Nano Banana 2...`);
  const stage1Results = await stage1VisualScreening(seedProduct, candidates);
  const stage1Filtered = [...stage1Results.values()].filter((r) => !r.passed).length;
  console.log(`[AI Verification] Stage 1 complete: ${stage1Filtered} filtered, ${candidates.length - stage1Filtered} passed to Stage 2`);
  console.log(`[AI Verification] Stage 2: Deep semantic verification with Gemini 3.1 Pro...`);
  const results = await stage2DeepVerification(seedProduct, candidates, stage1Results);
  for (const r of results) {
    const candidateAttrs = attributeMap.get(r.asin);
    if (candidateAttrs) {
      r.productAttributes = candidateAttrs;
    }
    if (seedAttrs && candidateAttrs) {
      const candidateProduct = candidates.find((c) => c.asin === r.asin);
      const matchDetails = computeAttributeMatch(
        seedAttrs,
        candidateAttrs,
        seedProduct.price,
        candidateProduct?.price || 0
      );
      r.attributeMatchDetails = matchDetails;
      r.overallSimilarity = Math.round(
        r.semanticScore * 0.6 + matchDetails.overallSimilarity * 0.4
      );
    } else {
      r.overallSimilarity = r.semanticScore;
    }
  }
  const summary = {
    total: candidates.length,
    trueCompetitors: results.filter((r) => r.result === "true_competitor").length,
    misplaced: results.filter((r) => r.result === "misplaced").length,
    partialMatch: results.filter((r) => r.result === "partial_match").length,
    stage1Filtered
  };
  console.log(`[AI Verification] Complete: ${summary.trueCompetitors} true competitors, ${summary.misplaced} misplaced, ${summary.partialMatch} partial matches`);
  return { results, summary };
}

