function buildCosmoIntentMatrix(cosmoMappings, causalChainData) {
  const byRelationType = {};
  for (const m of cosmoMappings) {
    if (!byRelationType[m.relationType]) {
      let fieldAllocation = "description";
      for (const [field, relations2] of Object.entries(COSMO_FIELD_ALLOCATION)) {
        if (relations2.includes(m.relationType)) {
          fieldAllocation = field;
          break;
        }
      }
      byRelationType[m.relationType] = {
        assertions: [],
        fieldAllocation,
        covered: false
      };
    }
    byRelationType[m.relationType].assertions.push(m.assertion);
  }
  const allRelationTypes = Object.keys(byRelationType);
  const uncoveredRelations = allRelationTypes.filter((r) => !byRelationType[r].covered);
  const coverageScore = allRelationTypes.length > 0 ? Math.round((allRelationTypes.length - uncoveredRelations.length) / allRelationTypes.length * 100) : 0;
  const matrixLines = [];
  for (const [relType, data] of Object.entries(byRelationType)) {
    const label = COSMO_RELATION_LABELS[relType] || relType;
    const topAssertions = data.assertions.slice(0, 3).join("; ");
    matrixLines.push(`- ${label} (${relType}): ${topAssertions} \u2192 Allocate to: ${data.fieldAllocation}`);
  }
  const topChains = [...causalChainData].sort((a, b) => (b.chainValue || 0) - (a.chainValue || 0)).slice(0, 5);
  if (topChains.length > 0) {
    matrixLines.push("\n=== High-Value Causal Chains (search intent \u2192 product attribute \u2192 user outcome) ===");
    for (const chain of topChains) {
      const attrs = Array.isArray(chain.productAttributes) ? chain.productAttributes.map((a) => `${a.attribute}: ${a.value}`).join(", ") : "";
      const coverage = [
        chain.titleCoverage ? "Title:\u2705" : "Title:\u274C",
        chain.bulletCoverage ? "Bullets:\u2705" : "Bullets:\u274C",
        chain.descriptionCoverage ? "Desc:\u2705" : "Desc:\u274C"
      ].join(" ");
      matrixLines.push(`  "${chain.searchIntent}" \u2192 [${attrs}] \u2192 "${chain.userOutcome || "N/A"}" (value: ${(chain.chainValue || 0).toFixed(2)}, coverage: ${coverage})`);
    }
  }
  const matrixText = matrixLines.join("\n");
  return { byRelationType, uncoveredRelations, coverageScore, matrixText };
}
