  PT04: { name: "\u526F\u56FE4 (Secondary 4)", purpose: "\u793E\u4F1A\u8BC1\u660E/\u8BC4\u4EF7/\u8BA4\u8BC1\u5C55\u793A", priority: "\u4E2D - \u4FE1\u4EFB\u80CC\u4E66" },
  PT05: { name: "\u526F\u56FE5 (Secondary 5)", purpose: "\u5305\u88C5\u5185\u5BB9/\u914D\u4EF6\u5C55\u793A", priority: "\u4E2D - \u5B8C\u6574\u6027\u5C55\u793A" },
  PT06: { name: "\u526F\u56FE6 (Secondary 6)", purpose: "\u54C1\u724C\u6545\u4E8B/\u5DEE\u5F02\u5316\u5356\u70B9", priority: "\u4E2D - \u54C1\u724C\u6EA2\u4EF7" },
  PT07: { name: "\u526F\u56FE7 (Secondary 7)", purpose: "FAQ/\u4F7F\u7528\u8BF4\u660E/\u4FDD\u4FEE\u4FE1\u606F", priority: "\u4F4E - \u6D88\u9664\u7591\u8651" },
  PT08: { name: "\u526F\u56FE8 (Secondary 8)", purpose: "\u5C3A\u5BF8/\u89C4\u683C/\u8865\u5145\u4FE1\u606F", priority: "\u4F4E - \u8865\u5145\u4FE1\u606F" },
  APLUS: { name: "A+ Content", purpose: "\u589E\u5F3A\u54C1\u724C\u5185\u5BB9\uFF0C\u6DF1\u5EA6\u54C1\u724C\u6545\u4E8B\u548C\u4EA7\u54C1\u8BE6\u60C5", priority: "\u4E2D - \u8F6C\u5316\u7387\u63D0\u5347" }
