        slotType: slot.slotType || "MAIN",
        imageSize: slot.imageSize || "2000x2000",
        contentBrief: slot.contentBrief || "",
        textElements: slot.textElements || {},
        visualElements: slot.visualElements || {},
        mobileSearchPreview: slot.mobileSearchPreview || {},
        pcSearchPreview: slot.pcSearchPreview || null,
