function r22(n) {
  return Math.round(n * 100) / 100;
}
function calculateThreatLevel(comp, project) {
  let threatScore = 0;
  if (comp.price && project?.productPrice && comp.price < project.productPrice * 0.9) threatScore += 3;
  else if (comp.price && project?.productPrice && comp.price < project.productPrice) threatScore += 1;
  if (comp.rating && project?.productRating && comp.rating > project.productRating + 0.3) threatScore += 2;
  if (comp.reviewCount && project?.productReviewsCount && comp.reviewCount > project.productReviewsCount * 2) threatScore += 2;
  else if (comp.reviewCount && project?.productReviewsCount && comp.reviewCount > project.productReviewsCount) threatScore += 1;
  return threatScore >= 5 ? "high" : threatScore >= 3 ? "medium" : "low";
}

