function formatCellValue(key, value) {
  if (value == null) return "";
  if (key === "purchaseRate" && typeof value === "number") return (value * 100).toFixed(2);
  if (key === "monthlyRevenue" && typeof value === "number") return value.toFixed(2);
  if (key === "overallSimilarity" && typeof value === "number") return value.toFixed(1);
  if (key === "valueScore" && typeof value === "number") return value.toFixed(1);
  if (key === "isNegative") return value ? "\u662F" : "\u5426";
  if (key === "type" && COPY_TYPE_LABELS[value]) return COPY_TYPE_LABELS[value];
  if (key === "version" && typeof value === "number") return `v${value}`;
  if (key === "createdAt" && value) return new Date(value).toISOString().slice(0, 10);
  if (typeof value === "object") return JSON.stringify(value);
  return String(value);
}
function buildCSV(rows, fields) {
  const headers = fields.map((f) => f.label);
  const csvRows = rows.map(
    (r) => fields.map((f) => formatCellValue(f.key, r[f.key])).map((v) => `"${String(v).replace(/"/g, '""')}"`).join(",")
  );
  return "\uFEFF" + headers.join(",") + "\n" + csvRows.join("\n");
}
async function buildExcel(rows, fields, sheetName) {
  const workbook = new ExcelJS2.Workbook();
  workbook.creator = "AmzOrbit";
  workbook.created = /* @__PURE__ */ new Date();
  const sheet = workbook.addWorksheet(sheetName);
  sheet.columns = fields.map((f) => ({
    header: f.label,
    key: f.key,
    width: Math.max(f.label.length * 2.5, 12)
  }));
  const headerRow = sheet.getRow(1);
  headerRow.font = { bold: true, color: { argb: "FFFFFFFF" } };
  headerRow.fill = {
    type: "pattern",
    pattern: "solid",
    fgColor: { argb: "FF1E3A5F" }
  };
  headerRow.alignment = { horizontal: "center", vertical: "middle" };
  headerRow.height = 24;
  for (const row of rows) {
    const values = {};
    for (const f of fields) {
      values[f.key] = formatCellValue(f.key, row[f.key]);
    }
    sheet.addRow(values);
  }
  sheet.autoFilter = {
    from: { row: 1, column: 1 },
    to: { row: 1, column: fields.length }
  };
  for (let i = 2; i <= rows.length + 1; i++) {
    const dataRow = sheet.getRow(i);
    if (i % 2 === 0) {
      dataRow.fill = {
        type: "pattern",
        pattern: "solid",
        fgColor: { argb: "FFF0F4F8" }
      };
    }
    dataRow.alignment = { vertical: "middle" };
  }
  sheet.views = [{ state: "frozen", ySplit: 1 }];
  const buffer = await workbook.xlsx.writeBuffer();
  return Buffer.from(buffer);
}
async function uploadExcel(buffer, filename) {
  const suffix = Math.random().toString(36).slice(2, 8);
  const key = `exports/${filename.replace(/[^a-zA-Z0-9._-]/g, "_")}-${suffix}.xlsx`;
  const { url } = await storagePut(key, buffer, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
  return url;
}
