  /** Get historical search volume trends for keywords */
  getKeywordSearchTrend: tenantProcedure.input(
    z26.object({
      projectId: z26.string(),
      keywordTexts: z26.array(z26.string()).min(1).max(10),
      months: z26.number().min(3).max(24).default(12)
    })
  ).query(async ({ ctx, input }) => {
    const project = await verifyProjectOwnership(input.projectId, ctx.user.id);
    const trends = [];
    const now = /* @__PURE__ */ new Date();
    const monthList = [];
    for (let i = input.months - 1; i >= 0; i--) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      monthList.push(
        `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`
      );
    }
    for (const keyword of input.keywordTexts) {
      const dataPoints = [];
      for (const month of monthList) {
        try {
          const result = await keywordResearch({
            userId: ctx.user.id,
            projectId: input.projectId,
            keyword,
            marketplace: project.marketplace || "US",
            month
          });
          const data = result;
          const items = data?.items || [];
          const matchItem = items.find(
            (item) => (item.keyword || item.keywords || "").toLowerCase() === keyword.toLowerCase()
          );
          if (matchItem) {
            dataPoints.push({
              month,
              searchVolume: matchItem.searches || matchItem.searchVolume || matchItem.monthlySearches || 0,
              purchaseRate: matchItem.purchaseRate || matchItem.buyRate,
              competitionLevel: matchItem.supplyDemand || matchItem.competitionLevel
            });
          } else if (data?.data?.searches || data?.searches) {
            dataPoints.push({
              month,
              searchVolume: data.data?.searches || data.searches || 0,
              purchaseRate: data.data?.purchaseRate || data.purchaseRate,
              competitionLevel: data.data?.supplyDemand || data.supplyDemand
            });
          } else {
            dataPoints.push({ month, searchVolume: 0 });
          }
        } catch (err) {
          dataPoints.push({ month, searchVolume: 0 });
        }
      }
      let googleTrendData;
      try {
        const gResult = await googleTrend({
          userId: ctx.user.id,
          projectId: input.projectId,
          keyword,
          marketplace: project.marketplace || "US"
        });
        const gData = gResult?.content?.[0]?.text ? JSON.parse(gResult.content[0].text) : gResult;
        const trendPoints = gData?.data?.items || gData?.items || gData?.data || [];
        if (Array.isArray(trendPoints) && trendPoints.length > 0) {
          googleTrendData = trendPoints.map((p) => ({
            date: p.date || p.formattedTime || p.month || "",
            value: p.value || p.interest || p.relativeInterest || 0
          }));
        }
      } catch {
      }
      trends.push({
        keyword,
        dataPoints,
        googleTrend: googleTrendData
      });
    }
    return { trends, monthRange: { from: monthList[0], to: monthList[monthList.length - 1] } };
  }),
