async function executePricingMonitor(projectId, yearWeek, project, thresholds) {
  const snapshots = await db.select().from(competitorWeeklySnapshots).where(
    and29(
      eq29(competitorWeeklySnapshots.projectId, projectId),
      eq29(competitorWeeklySnapshots.yearWeek, yearWeek)
    )
  );
  const prices = snapshots.filter((s) => s.price !== null).map((s) => Number(s.price));
  const avgPrice = prices.length > 0 ? prices.reduce((a, b) => a + b, 0) / prices.length : 0;
  const minPrice = prices.length > 0 ? Math.min(...prices) : 0;
  const maxPrice = prices.length > 0 ? Math.max(...prices) : 0;
  const [strategy] = await db.select().from(pricingStrategies).where(eq29(pricingStrategies.projectId, projectId)).limit(1);
  let ownPrice = project.ownProductPrice || project.productPrice || 0;
  if (strategy) {
    const [activeStage] = await db.select().from(pricingStages).where(eq29(pricingStages.strategyId, strategy.id)).limit(1);
    if (activeStage?.sellingPrice) {
      ownPrice = activeStage.sellingPrice;
    }
  }
  let pricePosition = "unknown";
  if (ownPrice && avgPrice) {
    if (ownPrice < avgPrice * 0.95) pricePosition = "below_avg";
    else if (ownPrice > avgPrice * 1.05) pricePosition = "above_avg";
    else pricePosition = "at_avg";
  }
  const priceChanges = snapshots.filter((s) => {
    const lc = s.listingChanges;
    return lc?.priceChange;
  }).map((s) => ({
    asin: s.asin,
    oldPrice: s.listingChanges.priceChange.previous,
    newPrice: s.listingChanges.priceChange.current,
    percentChange: s.listingChanges.priceChange.percentChange
  }));
  return {
    competitorPricesAnalyzed: prices.length,
    avgPrice: Math.round(avgPrice * 100) / 100,
    minPrice: Math.round(minPrice * 100) / 100,
    maxPrice: Math.round(maxPrice * 100) / 100,
    ownPrice,
    pricePosition,
    priceChangesDetected: priceChanges.length,
    priceChanges,
    recommendation: priceChanges.length > 0 ? `\u68C0\u6D4B\u5230 ${priceChanges.length} \u4E2A\u7ADE\u54C1\u4EF7\u683C\u53D8\u52A8\uFF0C\u5EFA\u8BAE\u8BC4\u4F30\u5B9A\u4EF7\u7B56\u7565` : "\u7ADE\u54C1\u4EF7\u683C\u7A33\u5B9A\uFF0C\u5F53\u524D\u5B9A\u4EF7\u7B56\u7565\u65E0\u9700\u8C03\u6574"
  };
}
