function detectScenario(input) {
  const { projectType, sourceProjectId, completedStepIds } = input;
  if (projectType === "research") {
    return {
      scenario: null,
      config: RESEARCH_STEPS,
      label: "\u8C03\u7814\u9879\u76EE"
    };
  }
  if (projectType === "pre_launch") {
    return {
      scenario: null,
      config: PRELAUNCH_STEPS,
      label: "\u9884\u53D1\u5E03\u9879\u76EE"
    };
  }
  if (projectType === "live_product") {
    const hasPrelaunchData = completedStepIds.includes(STEP_IDS.REVIEWS) && completedStepIds.includes(STEP_IDS.VOC_ANALYSIS) && completedStepIds.includes(STEP_IDS.PERSONA);
    if (sourceProjectId && hasPrelaunchData) {
      return {
        scenario: "incremental",
        config: LIVE_D0_INCREMENTAL_STEPS,
        label: "\u5728\u552E\u4EA7\u54C1\uFF08\u6D41\u7A0B\u8FC1\u79FB D0-Incremental\uFF09"
      };
    }
    const hasResearchData = completedStepIds.includes(STEP_IDS.KEYWORD_COLLECT) && completedStepIds.includes(STEP_IDS.COMPETITIVENESS);
    const lacksPrelaunchData = !completedStepIds.includes(STEP_IDS.REVIEWS);
    if (sourceProjectId && hasResearchData && lacksPrelaunchData) {
      return {
        scenario: "research_to_live",
        config: RESEARCH_TO_LIVE_STEPS,
        label: "\u5728\u552E\u4EA7\u54C1\uFF08\u8C03\u7814\u8DF3\u7EA7 Research\u2192Live\uFF09"
      };
    }
    return {
      scenario: "full",
      config: LIVE_D0_FULL_STEPS,
      label: "\u5728\u552E\u4EA7\u54C1\uFF08\u5B58\u91CF\u4EA7\u54C1 D0-Full\uFF09"
    };
  }
  return {
    scenario: null,
    config: RESEARCH_STEPS,
    label: "\u672A\u77E5\u7C7B\u578B"
  };
}
