async function retryStep(projectId, userId, stepId) {
  const [run] = await db.select().from(stepRuns).where(
    and30(
      eq30(stepRuns.projectId, projectId),
      eq30(stepRuns.stepId, stepId)
    )
  );
  if (!run) throw new Error(`Step ${stepId} not found for project ${projectId}`);
  if (run.status !== "failed" && run.status !== "blocked") {
    throw new Error(`Step ${stepId} is not in a retryable state (current: ${run.status})`);
  }
  await updateStepRun(projectId, stepId, {
    status: "pending",
    error: null,
    retryCount: (run.retryCount || 0) + 1
  });
  const meta = STEP_METADATA[stepId];
  if (meta) {
    const allStepIds = Object.values(STEP_IDS);
    for (const otherId of allStepIds) {
      const otherMeta = STEP_METADATA[otherId];
      if (otherMeta?.dependencies.includes(stepId)) {
        const [otherRun] = await db.select().from(stepRuns).where(
          and30(
            eq30(stepRuns.projectId, projectId),
            eq30(stepRuns.stepId, otherId)
          )
        );
        if (otherRun && otherRun.status === "blocked") {
          await updateStepRun(projectId, otherId, {
            status: "pending",
            error: null
          });
        }
      }
    }
  }
  const taskId = await enqueueTask({
    projectId,
    userId,
    type: "brand_product_init",
    input: { retryStep: stepId }
  });
  runStepEngine(projectId, userId, { taskId, singleStep: stepId }).catch(() => {
  });
  return { success: true, taskId };
}

