import { parse } from "cookie";
import { jwtVerify } from "jose";
import { eq as eq41 } from "drizzle-orm";
async function createContext({
  req,
  res
}) {
  let user = null;
  try {
    const cookies = parse(req.headers.cookie || "");
    const token = cookies[COOKIE_NAME];
    if (token && env.JWT_SECRET) {
      const secret = new TextEncoder().encode(env.JWT_SECRET);
      const { payload } = await jwtVerify(token, secret);
      const jwtId = payload.id;
      const openId = payload.openId || payload.open_id;
      let dbUser = null;
      if (jwtId) {
        const numId = parseInt(jwtId, 10);
        if (!isNaN(numId)) {
          dbUser = await db.query.users.findFirst({
            where: eq41(users.id, numId)
          });
        }
      }
      if (!dbUser && openId) {
        dbUser = await db.query.users.findFirst({
          where: eq41(users.openId, openId)
        });
      }
      if (dbUser) {
        const memberships = await db.select({
          tenantId: tenantMembers.tenantId,
          tenantRole: tenantMembers.role,
          memberStatus: tenantMembers.status,
          tenantName: tenants.name,
          tenantStatus: tenants.status,
          tenantPlan: tenants.plan,
          subscriptionEndDate: tenants.subscriptionEndDate
        }).from(tenantMembers).innerJoin(tenants, eq41(tenantMembers.tenantId, tenants.id)).where(eq41(tenantMembers.userId, String(dbUser.id)));
        const tenantMembershipsList = memberships.map((m) => ({
          tenantId: m.tenantId,
          tenantName: m.tenantName,
          tenantRole: m.tenantRole,
          memberStatus: m.memberStatus,
          tenantStatus: m.tenantStatus,
          tenantPlan: m.tenantPlan,
          subscriptionEndDate: m.subscriptionEndDate
        }));
        const activeMembership = tenantMembershipsList.find(
          (m) => m.memberStatus === "active" && m.tenantStatus === "active"
        );
        const preferredTenantId = payload.tenantId;
        const selectedMembership = preferredTenantId ? tenantMembershipsList.find(
          (m) => m.tenantId === preferredTenantId && m.memberStatus === "active" && m.tenantStatus === "active"
        ) || activeMembership : activeMembership;
        user = {
          id: String(dbUser.id),
          openId: dbUser.openId,
          name: dbUser.name || dbUser.realName || "",
          email: dbUser.email || "",
          avatar: "",
          role: dbUser.role,
          tenantId: selectedMembership?.tenantId || null,
          tenantName: selectedMembership?.tenantName || null,
          tenantRole: selectedMembership?.tenantRole || null,
          tenantMemberships: tenantMembershipsList
        };
      } else {
        console.warn("User not found in DB for JWT payload:", { jwtId, openId });
      }
    }
  } catch (err) {
    console.error("Context auth error:", err);
  }
  return { user, req, res };
}

