import fs from "fs";
import zlib2 from "zlib";
import path from "path";
import { fileURLToPath } from "url";
var __filename = fileURLToPath(import.meta.url);
var __dirname = path.dirname(__filename);
async function setupVite(app, httpServer) {
  if (process.env.NODE_ENV === "production") {
    const bundledPath = path.resolve(__dirname, "public");
    const sourcePath = path.resolve(__dirname, "..", "..", "dist", "public");
    const staticPath = fs.existsSync(bundledPath) ? bundledPath : sourcePath;
    const express2 = await import("express");
    // === Performance Optimization v26.7.2 ===
    // Gzip compression for all responses
    app.use((req, res, next) => {
      const acceptEncoding = req.headers["accept-encoding"] || "";
      if (acceptEncoding.includes("gzip")) {
        // Check if pre-compressed .gz file exists for static assets
        if (req.url.startsWith("/assets/") && !req.url.endsWith(".gz")) {
          const gzPath = path.join(staticPath, req.url + ".gz");
          try {
            if (fs.existsSync(gzPath)) {
              const ext = req.url.split(".").pop();
              const mimeTypes = { js: "application/javascript", css: "text/css", svg: "image/svg+xml" };
              res.setHeader("Content-Encoding", "gzip");
              res.setHeader("Content-Type", (mimeTypes[ext] || "application/octet-stream") + "; charset=UTF-8");
              res.setHeader("Cache-Control", "public, max-age=31536000, immutable");
              res.setHeader("Vary", "Accept-Encoding");
              return fs.createReadStream(gzPath).pipe(res);
            }
          } catch(e) {}
        }
      }
      next();
    });
    // Long-term cache for hashed assets
    app.use("/assets", (req, res, next) => {
      res.setHeader("Cache-Control", "public, max-age=31536000, immutable");
      res.setHeader("Vary", "Accept-Encoding");
      next();
    });
    // Runtime gzip for non-pre-compressed responses
    const zlib = zlib2;
    app.use((req, res, next) => {
      const acceptEncoding = req.headers["accept-encoding"] || "";
      if (!acceptEncoding.includes("gzip")) return next();
      const origWrite = res.write.bind(res);
      const origEnd = res.end.bind(res);
      const chunks = [];
      res.write = function(chunk) { chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk)); return true; };
      res.end = function(chunk) {
        if (chunk) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
        const body = Buffer.concat(chunks);
        if (body.length > 1024 && !res.getHeader("Content-Encoding")) {
          const ct = res.getHeader("Content-Type") || "";
          if (ct.includes("text/") || ct.includes("javascript") || ct.includes("json") || ct.includes("css") || ct.includes("xml")) {
            try {
              const compressed = zlib.gzipSync(body, { level: 6 });
              res.setHeader("Content-Encoding", "gzip");
              res.setHeader("Vary", "Accept-Encoding");
              res.removeHeader("Content-Length");
              origWrite(compressed);
              return origEnd();
            } catch(e) {}
          }
        }
        origWrite(body);
        origEnd();
      };
      next();
    });
    // === End Performance Optimization ===
    app.use(express2.default.static(staticPath));
    app.get("*", (_req, res) => {
      res.sendFile(path.join(staticPath, "index.html"));
    });
  } else {
    const { createServer: createServer2 } = await import("vite");
    const vite = await createServer2({
      server: {
        middlewareMode: true,
        hmr: httpServer ? { server: httpServer } : true
      },
      appType: "spa",
      configFile: path.resolve(__dirname, "..", "..", "vite.config.ts")
    });
    app.use(vite.middlewares);
  }
}

