// server/middleware/apiTiming.ts
function apiTimingMiddleware(req, res, next) {
  if (!req.path.startsWith("/api/")) {
    return next();
  }
  const start = performance.now();
  res.on("finish", () => {
    const duration = Math.round(performance.now() - start);
    recordApiMetric({
      path: req.path,
      method: req.method,
      statusCode: res.statusCode,
      duration,
      timestamp: Date.now()
    });
    if (!res.headersSent) {
      res.setHeader("Server-Timing", `api;dur=${duration}`);
    }
  });
  next();
}

// server/middleware/xray.ts
var AWSXRay = null;
var xrayEnabled = false;
async function initXRay(appName = "amzorbit-api") {
  try {
    AWSXRay = await import("aws-xray-sdk");
    AWSXRay.setDaemonAddress(process.env.AWS_XRAY_DAEMON_ADDRESS || "127.0.0.1:2000");
    AWSXRay.setContextMissingStrategy("LOG_ERROR");
    AWSXRay.captureHTTPsGlobal(await import("http"), true);
    AWSXRay.captureHTTPsGlobal(await import("https"), true);
    try {
      AWSXRay.captureMySQL(await import("mysql2"));
    } catch {
      console.log("[X-Ray] MySQL2 capture skipped (not available)");
    }
    xrayEnabled = true;
    console.log(`[X-Ray] Initialized for app: ${appName}`);
    return true;
  } catch (err) {
    console.log("[X-Ray] SDK not available, tracing disabled:", err.message);
    return false;
  }
}
function xrayMiddleware(appName = "amzorbit-api") {
  return (req, res, next) => {
    if (!xrayEnabled || !AWSXRay) {
      return next();
    }
    try {
      const segment = new AWSXRay.Segment(appName);
      const ns = AWSXRay.getNamespace();
      ns.run(() => {
        AWSXRay.setSegment(segment);
        segment.addAnnotation("http_method", req.method);
        segment.addAnnotation("url_path", req.path);
        if (req.headers["x-forwarded-for"]) {
          segment.addAnnotation("client_ip", String(req.headers["x-forwarded-for"]));
        }
        if (req.userId) {
          segment.addAnnotation("user_id", req.userId);
        }
        res.on("finish", () => {
          segment.addAnnotation("http_status", res.statusCode);
          if (res.statusCode >= 400 && res.statusCode < 500) {
            segment.addErrorFlag();
          } else if (res.statusCode >= 500) {
            segment.addFaultFlag();
          }
          segment.close();
        });
        res.on("error", (err) => {
          segment.addError(err);
          segment.close();
        });
        next();
      });
    } catch {
      next();
    }
  };
}

// server/migrate.ts
import { drizzle as drizzle2 } from "drizzle-orm/mysql2";
import { migrate } from "drizzle-orm/mysql2/migrator";
import mysql2 from "mysql2/promise";
import path2 from "path";
import { fileURLToPath as fileURLToPath2 } from "url";
var __dirname2 = path2.dirname(fileURLToPath2(import.meta.url));
async function getConnection() {
  const dbUrl2 = process.env.DATABASE_URL || "";
  if (!dbUrl2) {
    throw new Error("DATABASE_URL not set");
  }
  const needsSSL2 = dbUrl2.includes("tidbcloud.com") || dbUrl2.includes("ssl=true");
  return mysql2.createConnection({
    uri: dbUrl2.replace(/\?ssl=.*$/, ""),
    ...needsSSL2 ? { ssl: { rejectUnauthorized: true } } : {}
  });
}
async function getMigrationState(connection) {
  try {
    const [rows] = await connection.query(
      "SELECT * FROM `__drizzle_migrations` ORDER BY `created_at` ASC"
    );
    return rows;
  } catch {
    return [];
  }
}
async function backupMigrationState(connection, migrations, version) {
  try {
    await connection.query(`
      CREATE TABLE IF NOT EXISTS \`__migration_backups\` (
        \`id\` INT AUTO_INCREMENT PRIMARY KEY,
        \`version\` VARCHAR(100) NOT NULL,
        \`migration_count\` INT NOT NULL,
        \`migration_hashes\` TEXT NOT NULL,
        \`created_at\` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      )
    `);
    const hashes = migrations.map((m) => m.hash).join(",");
    await connection.query(
      "INSERT INTO `__migration_backups` (`version`, `migration_count`, `migration_hashes`) VALUES (?, ?, ?)",
      [version, migrations.length, hashes]
    );
    console.log(
      `[Migrate] Backed up migration state: ${migrations.length} migrations at version ${version}`
    );
  } catch (error) {
    console.warn(
      "[Migrate] Could not backup migration state:",
      error.message
    );
  }
}
async function rollbackToMigration(connection, targetHash) {
  const migrations = await getMigrationState(connection);
  const targetIdx = migrations.findIndex((m) => m.hash === targetHash);
  if (targetIdx === -1) {
    console.error(
      `[Migrate] Rollback target hash "${targetHash}" not found in migration history`
    );
    console.log(
      "[Migrate] Available migrations:",
      migrations.map((m) => m.hash)
    );
    return false;
  }
  const toRemove = migrations.slice(targetIdx + 1);
  if (toRemove.length === 0) {
    console.log("[Migrate] Already at target migration, nothing to rollback");
    return true;
  }
  console.log(
    `[Migrate] Rolling back ${toRemove.length} migration(s) after "${targetHash}"`
  );
  for (const migration of toRemove.reverse()) {
    console.log(`[Migrate]   Removing: ${migration.hash}`);
    await connection.query(
      "DELETE FROM `__drizzle_migrations` WHERE `hash` = ?",
      [migration.hash]
    );
  }
  console.log("[Migrate] Rollback complete. Removed migration records only.");
  console.log(
    "[Migrate] \u26A0\uFE0F  Schema changes (ALTER TABLE, etc.) were NOT reversed."
  );
  console.log(
    "[Migrate] If needed, apply reverse SQL manually before restarting."
  );
  return true;
}
async function runMigrations() {
  const dbUrl2 = process.env.DATABASE_URL || "";
  if (!dbUrl2) {
    console.error("[Migrate] DATABASE_URL not set, skipping migrations");
    return;
  }
  const isDryRun = process.env.DRY_RUN_MIGRATION === "true";
  const rollbackTarget = process.env.ROLLBACK_TO_MIGRATION;
  const appVersion = process.env.APP_VERSION || "unknown";
  const connection = await getConnection();
  try {
    const currentMigrations = await getMigrationState(connection);
    console.log(
      `[Migrate] Current state: ${currentMigrations.length} migration(s) applied`
    );
    if (rollbackTarget) {
      console.log(
        `[Migrate] Rollback requested to: ${rollbackTarget}`
      );
      if (isDryRun) {
        console.log("[Migrate] DRY RUN - would rollback but skipping");
        return;
      }
      await backupMigrationState(connection, currentMigrations, `pre-rollback-${appVersion}`);
      await rollbackToMigration(connection, rollbackTarget);
      return;
    }
    if (currentMigrations.length > 0) {
      await backupMigrationState(connection, currentMigrations, appVersion);
    }
    if (isDryRun) {
      console.log("[Migrate] DRY RUN mode - checking for pending migrations");
      const db3 = drizzle2(connection);
      console.log(
        "[Migrate] DRY RUN complete. Set DRY_RUN_MIGRATION=false to apply."
      );
      return;
    }
    console.log("[Migrate] Running pending migrations...");
    const db2 = drizzle2(connection);
    await migrate(db2, {
      migrationsFolder: path2.resolve(__dirname2, "../drizzle/migrations")
    });
    const newMigrations = await getMigrationState(connection);
    const applied = newMigrations.length - currentMigrations.length;
    if (applied > 0) {
      console.log(
        `[Migrate] \u2705 Applied ${applied} new migration(s). Total: ${newMigrations.length}`
      );
    } else {
      console.log("[Migrate] \u2705 No pending migrations. Schema is up to date.");
    }
  } catch (error) {
    console.error("[Migrate] \u274C Migration failed:", error.message);
    console.error(
      "[Migrate] Server will start despite migration failure."
    );
    console.error(
      "[Migrate] To rollback, set ROLLBACK_TO_MIGRATION=<hash> and restart."
    );
  } finally {
    await connection.end();
  }
}

